private void trackEventI(AdjustEvent event) {
    if (!checkActivityStateI(activityState)) return;
    if (!isEnabledI()) return;
    if (!checkEventI(event)) return;
    if (activityState.isGdprForgotten) return;
    if (!shouldProcessEventI(event.deduplicationId)) return;

    long now = System.currentTimeMillis();

    int sequence = eventMetadata.incrementSequenceForEvent(event.eventToken);

    activityState.eventCount++;
    updateActivityStateI(now);

    PackageBuilder eventBuilder = new PackageBuilder(
      adjustConfig, deviceInfo, activityState, globalParameters, firstSessionDelayManager, now);
    eventBuilder.internalState = internalState;
    ActivityPackage eventPackage = eventBuilder.buildEventPackage(event, sequence);
    packageHandler.addPackage(eventPackage);

    packageHandler.sendFirstPackage();

    // if it is in the background and it can send, start the background timer
    if (adjustConfig.isSendingInBackgroundEnabled && internalState.isInBackground()) {
        startBackgroundTimerI();
    }

    writeActivityStateI();
    writeEventMetadataI();
}

public int incrementSequenceForEvent(String eventToken) {
    @Nullable final Integer oldSequence = eventSequence.get(eventToken);

    // Sequence start at 1 when it does not exist
    final int newSequence = (oldSequence != null ? oldSequence : 0) + 1;

    eventSequence.put(eventToken, newSequence);

    return newSequence;
}

private void writeEventMetadataI() {
    synchronized (EventMetadata.class) {
        if (eventMetadata == null) {
            return;
        }
        Util.writeObject(eventMetadata, adjustConfig.context, EVENT_METADATA_FILENAME, EVENT_METADATA_NAME);
    }
}

