private void tryToGetResponse(final ResponseData responseData) {
    DataOutputStream dataOutputStream = null;

    try {
        String authorizationHeader = extractAuthorizationHeader(responseData.signedParameters);
        logger.verbose("authorizationHeader: %s", authorizationHeader);

        boolean shouldUseGET =
                responseData.activityPackage.getActivityKind() == ActivityKind.ATTRIBUTION;
        final String urlString;
        if (shouldUseGET) {
            urlString = generateUrlStringForGET(responseData.activityPackage.getActivityKind(),
                                                responseData.activityPackage.getPath(),
                                                responseData.activityPackage.getParameters(),
                                                responseData.sendingParameters,
                                                responseData.signedParameters);
        } else {
            urlString = generateUrlStringForPOST(responseData.activityPackage.getActivityKind(),
                                                 responseData.activityPackage.getPath(),
                                                 responseData.signedParameters);
        }

        final URL url = new URL(urlString);
        final HttpsURLConnection connection =
                httpsURLConnectionProvider.generateHttpsURLConnection(url);

        // get and apply connection options (default or for tests)
        connectionOptions.applyConnectionOptions(connection, clientSdk, connectionTimeout);

        if (authorizationHeader != null) {
            connection.setRequestProperty("Authorization", authorizationHeader);
        }

        if (shouldUseGET) {
            dataOutputStream = configConnectionForGET(connection);
        } else {
            dataOutputStream = configConnectionForPOST(connection,
                                                       responseData.activityPackage.getParameters(),
                                                       responseData.sendingParameters,
                                                       responseData.signedParameters);
        }

        // read connection response
        Integer responseCode = readConnectionResponse(connection, responseData);

        responseData.success =
                responseData.jsonResponse != null
                        && responseData.retryIn == null
                        && responseCode != null
                        && responseCode.intValue() == HttpsURLConnection.HTTP_OK;
        // it is only processed by the server if it contains
        //  a JSON response *AND* does not contain a retry_in
        responseData.willRetry =
                responseData.jsonResponse == null  || responseData.retryIn != null;

        if (responseData.jsonResponse == null) {
            responseData.activityPackage.addError(ErrorCodes.NULL_JSON_RESPONSE);
        } else if (responseData.retryIn != null) {
            responseData.activityPackage.addError(ErrorCodes.SERVER_RETRY_IN);
        }

    } catch (final UnsupportedEncodingException exception) {

        localError(exception, "Failed to encode parameters", responseData, ErrorCodes.UNSUPPORTED_ENCODING_EXCEPTION);

    } catch (final MalformedURLException exception) {

        localError(exception, "Malformed URL", responseData, ErrorCodes.MALFORMED_URL_EXCEPTION);

    } catch (final ProtocolException exception) {

        localError(exception, "Protocol Error", responseData, ErrorCodes.PROTOCOL_EXCEPTION);

    } catch (final SocketTimeoutException exception) {

        // timeout is remote/network related -> did not fail locally
        remoteError(exception, "Request timed out", responseData, ErrorCodes.SOCKET_TIMEOUT_EXCEPTION);

    } catch (final SSLHandshakeException exception) {

        // failed due certificate from the server -> did not fail locally
        remoteError(exception, "Certificate failed", responseData, ErrorCodes.SSL_HANDSHAKE_EXCEPTION);

    } catch (final IOException exception) {

        // IO is the network -> did not fail locally
        remoteError(exception, "Request failed", responseData, ErrorCodes.IO_EXCEPTION);

    } catch (final Throwable t) {

        // not sure if error is local or not -> assume it is local
        localError(t, "Sending SDK package", responseData, ErrorCodes.THROWABLE);

    } finally {
        try {
            if (dataOutputStream != null) {
                dataOutputStream.flush();
                dataOutputStream.close();
            }
        } catch (final IOException ioException) {
            String errorMessage = errorMessage(ioException,
                    "Flushing and closing connection output stream",
                    responseData.activityPackage);
            logger.error(errorMessage);
        }
    }
}

public void onResponseDataCallback(final ResponseData responseData) {
    logger.debug("Got response in PackageHandler");
    IActivityHandler activityHandler = activityHandlerWeakRef.get();
    if (activityHandler != null &&
            responseData.trackingState == TrackingState.OPTED_OUT) {
        activityHandler.gotOptOutResponse();
    }

    if (!responseData.willRetry) {
        scheduler.submit(new Runnable() {
            @Override
            public void run() {
                sendNextI(responseData.continueIn);
            }
        });

        if (activityHandler != null) {
            activityHandler.finishedTrackingActivity(responseData);
        }
        return;
    }

    if (!isRetrying) {
        isRetrying = true;
        retryStartedAtTimeMilliSeconds = System.currentTimeMillis();
    }

    writePackageQueueI();

    if (activityHandler != null) {
        activityHandler.finishedTrackingActivity(responseData);
    }

    Runnable runnable = new Runnable() {
        @Override
        public void run() {
            logger.verbose("Package handler can send");
            isSending.set(false);

            // Try to send the same package after sleeping
            sendFirstPackage();
        }
    };

    if (responseData.retryIn != null) {
        long retryIn = responseData.retryIn;
        scheduler.schedule(runnable, retryIn);
        return;
    }

    int retries = responseData.activityPackage.increaseRetries();
    long waitTimeMilliSeconds;

    SharedPreferencesManager sharedPreferencesManager = SharedPreferencesManager.getDefaultInstance(context);

    if (responseData.activityPackage.getActivityKind() ==
            ActivityKind.SESSION && !sharedPreferencesManager.getInstallTracked()) {
        waitTimeMilliSeconds = Util.getWaitingTime(retries, backoffStrategyForInstallSession);
    } else {
        waitTimeMilliSeconds = Util.getWaitingTime(retries, backoffStrategy);
    }

    double waitTimeSeconds = waitTimeMilliSeconds / 1000.0;
    String secondsString = Util.SecondsDisplayFormat.format(waitTimeSeconds);

    totalWaitTimeSeconds += waitTimeSeconds;

    logger.verbose("Waiting for %s seconds before retrying %s for the %d time",
            secondsString,
            responseData.activityPackage.getActivityKind().toString(),
            retries);
    scheduler.schedule(runnable, waitTimeMilliSeconds);
    responseData.activityPackage.setWaitBeforeSendTimeSeconds(responseData.activityPackage.getWaitBeforeSendTimeSeconds() + waitTimeSeconds);
}

private void sendNextI(Long previousResponseContinueIn) {
    isRetrying = false;
    retryStartedAtTimeMilliSeconds = 0;

    if (packageQueue.isEmpty()) {
        // at this point, the queue has been emptied
        // reset total_wait in this moment to allow all requests to populate total_wait
        totalWaitTimeSeconds = 0.0;
        return;
    }

    packageQueue.remove(0);
    writePackageQueueI();

    if (previousResponseContinueIn != null && previousResponseContinueIn > 0) {
        Runnable runnable = new Runnable() {
            @Override
            public void run() {
                logger.verbose("Package handler finished waiting to continue");
                isSending.set(false);
                sendFirstPackage();
            }
        };

        logger.verbose("Waiting for %d seconds before continuing for next package in continue_in", previousResponseContinueIn / 1000.0);
        scheduler.schedule(runnable, previousResponseContinueIn);

    } else {
        logger.verbose("Package handler can send");
        isSending.set(false);
        sendFirstI();
    }
}

public static long getWaitingTime(int retries, BackoffStrategy backoffStrategy) {
    if (retries < backoffStrategy.minRetries) {
        return 0;
    }
    // start with expon 0
    int expon = retries - backoffStrategy.minRetries;
    // get the exponential Time from the power of 2: 1, 2, 4, 8, 16, ... * times the multiplier
    long exponentialTime = ((long) Math.pow(2, expon)) * backoffStrategy.milliSecondMultiplier;
    // limit the maximum allowed time to wait
    long ceilingTime = Math.min(exponentialTime, backoffStrategy.maxWait);
    // get the random range
    double randomDouble = randomInRange(backoffStrategy.minRange, backoffStrategy.maxRange);
    // apply jitter factor
    double waitingTime =  ceilingTime * randomDouble;
    return (long)waitingTime;
}

